/* Эмуляция коллег во встроенном сервере прототипа: они берут события из общей очереди,
   проходят свои сценарии и закрывают инциденты, передают инцидент оператору и теряют связь.
   Всё — через переходы машины от имени коллеги, с его правами и лимитом активных; потеря
   связи — системными переходами по признаку активности (§12.3). Для живости демо: в эталонный
   набор данных (fixtures/demo.json) не входит; проверяет её тест в tests/api-scenarios.js. */
(() => {
  const SIM = {
    enabled: true,
    // Берут события по очереди, если свободны: лимит активных у каждого свой (§10.2)
    colleagues: ["noc", "sidorov", "petrova", "gusev"],
    firstTakeSec: 12,
    takeEverySec: 24,
    stepEverySec: 11,
    handoffSec: 46,
    dropSec: 88,
    maxTaken: 3,
    taken: 0,
    takeTick: 0,
    stepTick: 0,
    handoffTick: 0,
    dropTick: 0,
    handoffDone: false,
    dropDone: false,
  };

  const SIM_NOTES = [
    "Охрана направлена, время прибытия 2 мин",
    "Передано бригадиру, акт №14-СБ",
    "Уточняю по архиву, свидетелей нет",
    "Наряд на месте, инцидент локализован",
  ];

  window.IM_COLLEAGUES = { SIM, SIM_NOTES };
})();
